func btNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func btNext(b []byte, i int32, lim int32, ch int32) int32 {
	// Index of the next byte `ch` in [i, lim), or lim.
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != ch) {
		k += 1
	}
	return k
}

func btDigit(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 65) && (c <= 70) {
		return c - 55
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	return -1
}

func btNums(b []byte, from int32, to int32, base int32, c *port.Cells) int32 {
	// Parse the numbers (written in `base`, 10 or 16) separated by spaces in b[from, to) onto c, cleared first.
	// Answers how many.
	var k int32 = from
	var v int32 = 0
	var in int32 = 0
	var d int32 = 0
	port.CellsDrop(c, 0)
	for k < to {
		d = btDigit(port.BlobU8(b, k))
		if (d >= 0) && (d < base) {
			v = (v * base) + d
			in = 1
		} else if in == 1 {
			port.CellsPush(c, v)
			v = 0
			in = 0
		}
		k += 1
	}
	if in == 1 {
		port.CellsPush(c, v)
	}
	return port.CellsLen(c)
}

func TestEveryClaimedRowOfBidiCharacterTestTxt(emonT *testing.T) {
	var f []byte = port.TestFile("bidi/conformance.txt")
	var ar *port.Cells = port.NewCells()
	var wantLv *port.Cells = port.NewCells()
	var wantVis *port.Cells = port.NewCells()
	var end int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var n int32 = 0
	var o int32 = 0
	var k int32 = 0
	var badl int32 = 0
	var badv int32 = 0
	for pos < end {
		line += 1
		e = btNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s1 = btNext(f, pos, e, 59)
			s2 = btNext(f, s1+1, e, 59)
			port.CellsDrop(ar, 0)
			n = btNums(f, pos, s1, 16, ar)
			btNums(f, s1+1, s2, 10, wantLv)
			btNums(f, s2+1, e, 10, wantVis)
			o = bidi.BdOrderOf(ar, 0, n)
			badl = 0
			badv = 0
			k = 0
			for k < n {
				if port.CellsAt(ar, (o-n)+k) != port.CellsAt(wantLv, k) {
					badl += 1
				}
				if port.CellsAt(ar, o+k) != port.CellsAt(wantVis, k) {
					badv += 1
				}
				k += 1
			}
			port.AssertEqAt(emonT, badl, 0, "characters with a wrong level", line)
			port.AssertEqAt(emonT, badv, 0, "positions in the wrong visual order", line)
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows > 1000, "the corpus has its rows")
}

func TestClassesOfTheCharactersThatMatter(emonT *testing.T) {
	port.AssertEq(emonT, bidi.BdClass(1488), 1, "alef is R")
	port.AssertEq(emonT, bidi.BdClass(1575), 8, "arabic alif is AL")
	port.AssertEq(emonT, bidi.BdClass(48), 3, "0 is EN")
	port.AssertEq(emonT, bidi.BdClass(1632), 4, "arabic-indic zero is AN")
	port.AssertEq(emonT, bidi.BdClass(1776), 3, "extended arabic-indic zero is EN")
	port.AssertEq(emonT, bidi.BdClass(37), 6, "% is ET")
	port.AssertEq(emonT, bidi.BdClass(36), 6, "$ is ET")
	port.AssertEq(emonT, bidi.BdClass(1642), 6, "arabic percent sign is ET")
	port.AssertEq(emonT, bidi.BdClass(44), 7, ", is CS")
	port.AssertEq(emonT, bidi.BdClass(47), 7, "/ is CS")
	port.AssertEq(emonT, bidi.BdClass(1548), 7, "arabic comma is CS")
	port.AssertEq(emonT, bidi.BdClass(45), 5, "hyphen-minus is ES")
	port.AssertEq(emonT, bidi.BdClass(43), 5, "+ is ES")
	port.AssertEq(emonT, bidi.BdClass(1456), 10, "a hebrew point is NSM")
	port.AssertEq(emonT, bidi.BdClass(97), 2, "a is L")
	port.AssertEq(emonT, bidi.BdClass(32), 9, "space is WS")
	port.AssertEq(emonT, bidi.BdClass(-1), 0, "no value is neutral")
	port.AssertEq(emonT, bidi.BdMirror(40), 41, "( mirrors to )")
	port.AssertEq(emonT, bidi.BdMirror(41), 40, ") mirrors to (")
	port.AssertEq(emonT, bidi.BdMirror(60), 62, "< mirrors to >")
	port.AssertEq(emonT, bidi.BdMirror(187), 171, "a right guillemet mirrors to the left one")
	port.AssertEq(emonT, bidi.BdMirror(97), 97, "a letter mirrors to itself")
	port.AssertEq(emonT, bidi.BdStrong(1488), 1, "alef is a strong R letter")
	port.AssertEq(emonT, bidi.BdStrong(1575), 1, "alif is a strong R letter")
	port.AssertEq(emonT, bidi.BdStrong(97), 2, "a is a strong L letter")
	port.AssertEq(emonT, bidi.BdStrong(48), 0, "a digit is not strong")
	port.AssertEq(emonT, bidi.BdStrong(44), 0, "a comma is not strong")
}

func btShownAsLogical(a *port.Cells, n int32, want *port.Cells, ar *port.Cells) int32 {
	// 1 when the order the algorithm gives for the code points a[0, n) (read as shown), each mirrored where its
	// level is odd (L4), lists want.
	var k int32 = 0
	var i int32 = 0
	var cp int32 = 0
	var o int32 = 0
	if n != port.CellsLen(want) {
		return 0
	}
	port.CellsDrop(ar, 0)
	for k < n {
		port.CellsPush(ar, port.CellsAt(a, k))
		k += 1
	}
	o = bidi.BdOrderOf(ar, 0, n)
	k = 0
	for k < n {
		i = port.CellsAt(ar, o+k)
		cp = port.CellsAt(a, i)
		if port.CellsAt(ar, (o-n)+i) == 1 {
			cp = bidi.BdMirror(cp)
		}
		if cp != port.CellsAt(want, k) {
			return 0
		}
		k += 1
	}
	return 1
}

func TestHebrewAndArabicSamplesShownAndLogical(emonT *testing.T) {
	var f []byte = port.TestFile("bidi/samples.txt")
	var shown *port.Cells = port.NewCells()
	var logical *port.Cells = port.NewCells()
	var ar *port.Cells = port.NewCells()
	var end int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var t1 int32 = 0
	var t2 int32 = 0
	var n int32 = 0
	var m int32 = 0
	for pos < end {
		line += 1
		e = btNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			t1 = btNext(f, pos, e, 9)
			t2 = btNext(f, t1+1, e, 9)
			port.CellsDrop(shown, 0)
			port.CellsDrop(logical, 0)
			n = model.TextAppendUtf8(shown, f, pos, t1)
			m = model.TextAppendUtf8(logical, f, t1+1, t2)
			port.AssertEqAt(emonT, btShownAsLogical(shown, n, logical, ar), 1, "what is shown, put in logical order, is the logical text", line)
			port.AssertEqAt(emonT, btShownAsLogical(logical, m, shown, ar), 1, "the logical text, put in display order, is what is shown", line)
		}
		pos = e + 1
	}
	port.AssertEq(emonT, rows, 23, "the samples")
}
